package antigravity

import (
	"context"
	"encoding/json"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/cblabs-org/repo-memory-plugin/internal/core/config"
	"github.com/cblabs-org/repo-memory-plugin/internal/core/delivery"
	"github.com/cblabs-org/repo-memory-plugin/internal/core/index"
)

var allowResponse = []byte(`{"decision":"allow"}`)

type PreToolUsePayload struct {
	ConversationID      string   `json:"conversationId"`
	ConversationIDSnake string   `json:"conversation_id"`
	InvocationNum       int      `json:"invocationNum"`
	ToolName            string   `json:"toolName"`
	ToolNameSnake       string   `json:"tool_name,omitempty"`
	ToolCall            struct {
		Name string          `json:"name"`
		Args json.RawMessage `json:"args"`
	} `json:"toolCall"`
	TranscriptPath      string   `json:"transcriptPath"`
	TranscriptPathSnake string   `json:"transcript_path"`
	WorkspacePaths      []string `json:"workspacePaths"`
	WorkspacePathsSnake []string `json:"workspace_paths"`
}

func (p *PreToolUsePayload) Normalize() {
	if p.ConversationID == "" {
		p.ConversationID = p.ConversationIDSnake
	}
	if p.TranscriptPath == "" {
		p.TranscriptPath = p.TranscriptPathSnake
	}
	if len(p.WorkspacePaths) == 0 {
		p.WorkspacePaths = p.WorkspacePathsSnake
	}
	if p.ToolName == "" {
		p.ToolName = p.ToolNameSnake
	}
	if p.ToolName == "" && p.ToolCall.Name != "" {
		p.ToolName = p.ToolCall.Name
	}
}

type PreToolUseResponse struct {
	Decision string `json:"decision"` // "allow", "deny", "ask", "force_ask"
	Reason   string `json:"reason,omitempty"`
}

func HandlePreToolUse(ctx context.Context, payload []byte, opts ...HookOption) ([]byte, error) {
	if ctx == nil {
		ctx = context.Background()
	}

	if len(strings.TrimSpace(string(payload))) == 0 {
		return allowResponse, nil
	}

	var input PreToolUsePayload
	if err := json.Unmarshal(payload, &input); err != nil {
		return allowResponse, nil
	}
	input.Normalize()

	if os.Getenv("REPO_MEMORY_DISABLED") == "1" || strings.EqualFold(os.Getenv("REPO_MEMORY_DISABLED"), "true") {
		return allowResponse, nil
	}
	if os.Getenv("REPO_MEMORY_HOUSEKEEPING") == "1" || strings.EqualFold(os.Getenv("REPO_MEMORY_HOUSEKEEPING"), "true") {
		return allowResponse, nil
	}

	toolName := strings.ToLower(strings.TrimSpace(input.ToolName))
	if toolName != "replace_file_content" && toolName != "write_to_file" {
		return allowResponse, nil
	}

	var hookOpts HookOptions
	for _, opt := range opts {
		if opt != nil {
			opt(&hookOpts)
		}
	}

	workspaceRoot := hookOpts.WorkspaceOverride
	if workspaceRoot == "" {
		if len(input.WorkspacePaths) > 0 && input.WorkspacePaths[0] != "" {
			workspaceRoot = input.WorkspacePaths[0]
		} else {
			workspaceRoot, _ = os.Getwd()
		}
	}
	if workspaceRoot == "" {
		return allowResponse, nil
	}

	if isHousekeepingPath(workspaceRoot) {
		return allowResponse, nil
	}

	if !config.IsEnrolledFast(workspaceRoot) {
		return allowResponse, nil
	}

	dataDir := hookOpts.DataDir
	if dataDir == "" {
		dataDir = config.DataDir()
	}

	repoID := ""
	if entry, found, _ := config.FindRegistryEntry(dataDir, workspaceRoot); found && entry != nil {
		repoID = entry.RepoID
		if repoCfg, err := config.LoadRepoConfig(entry.RootPath); err == nil && !repoCfg.IsEnabled() {
			return allowResponse, nil
		}
	}
	if repoID == "" {
		cmd := exec.Command("git", "rev-parse", "--show-toplevel")
		cmd.Dir = workspaceRoot
		out, err := cmd.Output()
		if err == nil {
			repoID = filepath.Base(strings.TrimSpace(string(out)))
		}
	}
	if repoID == "" {
		return allowResponse, nil
	}

	targetFile := extractTargetFile(input.ToolCall.Args)
	if targetFile == "" {
		return allowResponse, nil
	}

	idxPath := filepath.Join(dataDir, repoID, "index.db")
	idx, err := index.NewIndex(idxPath)
	if err != nil {
		return allowResponse, nil
	}
	defer idx.Close()

	engine := delivery.NewEngine(idx, workspaceRoot)
	ledger := delivery.NewLedger(input.ConversationID)

	entries, err := engine.GateEntries(ctx, targetFile, ledger)
	if (err != nil || len(entries) == 0) && filepath.IsAbs(targetFile) {
		if rel, errRel := filepath.Rel(workspaceRoot, targetFile); errRel == nil && !strings.HasPrefix(rel, "..") {
			entries, _ = engine.GateEntries(ctx, rel, ledger)
		}
	} else if (err != nil || len(entries) == 0) && !filepath.IsAbs(targetFile) {
		absPath := filepath.Join(workspaceRoot, targetFile)
		entries, _ = engine.GateEntries(ctx, absPath, ledger)
	}

	if len(entries) == 0 {
		return allowResponse, nil
	}

	ledger.AcknowledgeGate(entries[0].Entry.ID)
	denyMsg := delivery.FormatGateDeny(entries[0].Entry)
	resp := PreToolUseResponse{
		Decision: "force_ask",
		Reason:   denyMsg,
	}

	out, err := json.Marshal(resp)
	if err != nil {
		return allowResponse, nil
	}
	return out, nil
}

type editArgs struct {
	TargetFile        string `json:"TargetFile"`
	TargetFileCamel   string `json:"targetFile"`
	TargetFileSnake   string `json:"target_file"`
	FilePath          string `json:"FilePath"`
	FilePathCamel     string `json:"filePath"`
	FilePathSnake     string `json:"file_path"`
	AbsolutePath      string `json:"AbsolutePath"`
	AbsolutePathCamel string `json:"absolutePath"`
	Path              string `json:"path"`
}

func extractTargetFile(argsRaw json.RawMessage) string {
	if len(argsRaw) == 0 {
		return ""
	}

	var args editArgs
	if err := json.Unmarshal(argsRaw, &args); err == nil {
		if t := pickTarget(args); t != "" {
			return t
		}
	}

	var str string
	if err := json.Unmarshal(argsRaw, &str); err == nil && str != "" {
		var strArgs editArgs
		if err := json.Unmarshal([]byte(str), &strArgs); err == nil {
			if t := pickTarget(strArgs); t != "" {
				return t
			}
		}
	}

	var m map[string]any
	if err := json.Unmarshal(argsRaw, &m); err == nil {
		for _, key := range []string{"TargetFile", "targetFile", "target_file", "FilePath", "filePath", "file_path", "AbsolutePath", "absolutePath", "path", "file"} {
			if val, ok := m[key]; ok {
				if s, ok := val.(string); ok && s != "" {
					return s
				}
			}
		}
	}

	return ""
}

func pickTarget(a editArgs) string {
	switch {
	case a.TargetFile != "":
		return a.TargetFile
	case a.TargetFileCamel != "":
		return a.TargetFileCamel
	case a.TargetFileSnake != "":
		return a.TargetFileSnake
	case a.FilePath != "":
		return a.FilePath
	case a.FilePathCamel != "":
		return a.FilePathCamel
	case a.FilePathSnake != "":
		return a.FilePathSnake
	case a.AbsolutePath != "":
		return a.AbsolutePath
	case a.AbsolutePathCamel != "":
		return a.AbsolutePathCamel
	case a.Path != "":
		return a.Path
	default:
		return ""
	}
}

