func TestPreToolUse_EditWithGate(t *testing.T) {
	ctx := context.Background()
	workspace, idxPath := setupEnrolledWorkspace(t)

	// Create target file on disk so anchor verification passes
	targetFile := filepath.Join(workspace, "critical_config.go")
	if err := os.WriteFile(targetFile, []byte("package config\n"), 0644); err != nil {
		t.Fatal(err)
	}

	// Seed index with gated entry
	idx, err := index.NewIndex(idxPath)
	if err != nil {
		t.Fatal(err)
	}
	gatedEntry := dossiers.Entry{
		ID:           "gate-crit-01",
		Type:         dossiers.EntryTypeInvariant,
		DossierScope: "config",
		Text:         "Do not edit directly without running backup gate: edit",
		Anchors:      []string{"critical_config.go"},
	}
	if err := idx.UpsertEntry(ctx, gatedEntry); err != nil {
		t.Fatal(err)
	}
	if err := idx.UpsertEntryAnchors(ctx, gatedEntry.ID, gatedEntry.Anchors); err != nil {
		t.Fatal(err)
	}
	idx.Close()

	// Test with replace_file_content using absolute path
	payloadReplace := `{
		"conversationId": "conv-gate-test",
		"toolName": "replace_file_content",
		"toolCall": {
			"name": "replace_file_content",
			"args": {"TargetFile": "` + targetFile + `"}
		},
		"workspacePaths": ["` + workspace + `"]
	}`

	out, err := HandlePreToolUse(ctx, []byte(payloadReplace))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	var resp PreToolUseResponse
	if err := json.Unmarshal(out, &resp); err != nil {
		t.Fatalf("failed to unmarshal output %q: %v", string(out), err)
	}

	if resp.Decision != "force_ask" {
		t.Errorf("expected decision 'force_ask', got %q", resp.Decision)
	}

	// Verify response reason contains [REPO-MEMORY tag, entry ID, and gate text
	if !strings.Contains(resp.Reason, "[REPO-MEMORY") {
		t.Errorf("expected [REPO-MEMORY tag in reason, got %q", resp.Reason)
	}
	if !strings.Contains(resp.Reason, "gate-crit-01") {
		t.Errorf("expected entry ID 'gate-crit-01' in reason, got %q", resp.Reason)
	}
	if !strings.Contains(resp.Reason, "gate: edit") {
		t.Errorf("expected gate text in reason, got %q", resp.Reason)
	}

	// Test with write_to_file using relative path
	payloadWrite := `{
		"conversationId": "conv-gate-test",
		"toolName": "write_to_file",
		"toolCall": {
			"name": "write_to_file",
			"args": {"TargetFile": "critical_config.go"}
		},
		"workspacePaths": ["` + workspace + `"]
	}`

	outWrite, err := HandlePreToolUse(ctx, []byte(payloadWrite))
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}

	var respWrite PreToolUseResponse
	if err := json.Unmarshal(outWrite, &respWrite); err != nil {
		t.Fatalf("failed to unmarshal output: %v", err)
	}
	if respWrite.Decision != "force_ask" {
		t.Errorf("expected decision 'force_ask' for write_to_file, got %q", respWrite.Decision)
	}
	if !strings.Contains(respWrite.Reason, "[REPO-MEMORY") {
		t.Errorf("expected [REPO-MEMORY tag in write_to_file reason, got %q", respWrite.Reason)
	}
}

