func TestHookCmd_PreToolUse(t *testing.T) {
	origWorkspace := hookWorkspaceFlag
	defer func() { hookWorkspaceFlag = origWorkspace }()
	hookWorkspaceFlag = ""

	dataDir := t.TempDir()
	t.Setenv("REPO_MEMORY_DATA_DIR", dataDir)

	repoDir := t.TempDir()
	_ = config.CreateEnrolledMarker(repoDir)
	repoID := "test-pretool-repo"
	if err := config.AddToRegistry(dataDir, []string{repoDir}, repoID, repoDir); err != nil {
		t.Fatalf("AddToRegistry: %v", err)
	}

	targetFile := filepath.Join(repoDir, "secure.go")
	if err := os.WriteFile(targetFile, []byte("package secure\n"), 0644); err != nil {
		t.Fatal(err)
	}

	// 1. Un-gated edit -> allow
	var stdin bytes.Buffer
	var stdout bytes.Buffer
	payload := `{"conversationId":"conv-pre","toolName":"replace_file_content","toolCall":{"name":"replace_file_content","args":{"TargetFile":"` + targetFile + `"}},"workspacePaths":["` + repoDir + `"]}`
	stdin.WriteString(payload)
	hookCmd.SetIn(&stdin)
	hookCmd.SetOut(&stdout)

	err := hookCmd.RunE(hookCmd, []string{"antigravity", "PreToolUse"})
	if err != nil {
		t.Fatalf("hookCmd.RunE failed: %v", err)
	}
	if strings.TrimSpace(stdout.String()) != `{"decision":"allow"}` {
		t.Errorf("expected allow for un-gated edit, got %q", stdout.String())
	}

	// 2. Gated edit -> force_ask
	idxPath := filepath.Join(dataDir, repoID, "index.db")
	_ = os.MkdirAll(filepath.Dir(idxPath), 0755)
	idx, err := index.NewIndex(idxPath)
	if err != nil {
		t.Fatal(err)
	}
	entry := dossiers.Entry{
		ID:           "gate-hook-01",
		Type:         dossiers.EntryTypeInvariant,
		DossierScope: "secure",
		Text:         "Security sensitive edit gate: edit",
		Anchors:      []string{"secure.go"},
	}
	ctx := context.Background()
	_ = idx.UpsertEntry(ctx, entry)
	_ = idx.UpsertEntryAnchors(ctx, entry.ID, entry.Anchors)
	idx.Close()

	stdin.Reset()
	stdout.Reset()
	stdin.WriteString(payload)
	hookCmd.SetIn(&stdin)
	hookCmd.SetOut(&stdout)

	err = hookCmd.RunE(hookCmd, []string{"antigravity", "PreToolUse"})
	if err != nil {
		t.Fatalf("hookCmd.RunE failed: %v", err)
	}
	outStr := strings.TrimSpace(stdout.String())
	if !strings.Contains(outStr, `"decision":"force_ask"`) {
		t.Errorf("expected decision force_ask, got %q", outStr)
	}
	if !strings.Contains(outStr, "[REPO-MEMORY") || !strings.Contains(outStr, "gate-hook-01") {
		t.Errorf("expected gate tag and ID in output, got %q", outStr)
	}
}
